# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, A, DN, GB, M = "Lucas", "Amparo", "Daniel", "Gaby", "Mercedes"
D = [
("#", "Escena 1 · 20:15 · Casa de los Ruiz-Walker, Coral Gables", "장면 1 · 오후 8시 15분 · 코럴게이블스, 루이스-워커 가족의 집"),
(None, "Miércoles 22 de julio. Una casa de estilo mediterráneo, con tejas rojas, una buganvilla en la entrada y un césped perfecto. Lucas lleva una botella de vino de Castellón; Amparo, una caja pequeña envuelta en papel. Les abre Gaby, descalza, con un vaso de agua en la mano.", "7월 22일 수요일. 붉은 기와, 입구의 부겐빌레아, 완벽하게 다듬은 잔디가 있는 지중해풍 집. 루카스는 카스테욘 와인 한 병을, 암파로는 종이로 싼 작은 상자를 들고 있다. 맨발에 물잔을 든 가비가 문을 연다."),
(GB, "¡Ocho y cuarto en punto! Bien hecho. Mi papá todavía no ha bajado. ¿Dónde parquearon?", "8시 15분 정각! 잘하셨어요. 아빠는 아직 안 내려왔어요. 어디 주차했어요?"),
(L, "Delante de la casa. Espero que no esté prohibido.", "집 앞에요. 금지 구역이 아니면 좋겠네요."),
(GB, "Está bien. Aquí el problema no es parquear, es cortar la yarda. Mi papá se pelea con el vecino por el césped cada sábado.", "괜찮아요. 여기서 문제는 주차가 아니라 마당 잔디 깎기예요. 아빠는 토요일마다 잔디 때문에 이웃이랑 싸워요."),
(A, "¿La yarda?", "'야르다'요?"),
(GB, "El jardín. Yard. Perdón, es que en esta casa hablamos así. Ya verán con mi abuela.", "정원이요. 야드. 미안해요, 이 집에선 이렇게 말해요. 할머니랑 얘기해 보면 아실 거예요."),
(None, "En el salón, una mujer de unos ochenta y cinco años, pequeña, muy derecha, con el pelo blanco recogido y un collar de perlas, se levanta despacio de un sillón.", "거실에서 여든다섯쯤 된 작고 꼿꼿한 여인이 흰 머리를 올리고 진주 목걸이를 한 채 안락의자에서 천천히 일어난다."),
(M, "¡Así que estos son los gallegos! Acérquense, mi'jo, que ya no veo de lejos.", "그러니까 이 사람들이 그 갈레고들이구나! 가까이 와요, 얘야. 이제 멀리는 잘 안 보여."),
(GB, "Abuela, te presento a Lucas y a Amparo. Abuela Mercedes.", "할머니, 루카스랑 암파로예요. 메르세데스 할머니."),
(L, "Encantado, señora. Gracias por invitarnos a su casa.", "반갑습니다, 할머님. 댁에 초대해 주셔서 감사합니다."),
(M, "¡Qué bueno que hayan venido! En esta casa, cuando viene alguien de España, es como si viniera un primo.", "와 줘서 정말 좋구나! 이 집에선 스페인에서 누가 오면 사촌이 온 것 같아."),
(A, "Le hemos traído una cosa pequeña. Es de nuestra fábrica.", "작은 걸 하나 가져왔어요. 저희 공장에서 만든 거예요."),
(None, "Mercedes abre la caja. Dentro hay una baldosa pequeña, de veinte por veinte, con un dibujo geométrico azul y blanco, como los antiguos mosaicos hidráulicos.", "메르세데스가 상자를 연다. 안에는 옛 시멘트 모자이크 타일처럼 파랑과 흰색 기하학 무늬가 그려진 20×20짜리 작은 타일 하나가 들어 있다."),
(M, "(se queda callada un momento) ¡Ay, Dios mío! ¿Y esto?", "(잠시 말이 없다가) 어머나, 세상에! 이게 뭐야?"),
(A, "Es una reproducción de un diseño de los años cincuenta. Mi abuelo lo hacía a mano, antes de las máquinas.", "50년대 디자인을 다시 만든 거예요. 기계가 나오기 전에 저희 할아버지가 손으로 만들던 거예요."),
(M, "Este dibujo yo lo he pisado, mi'ja. Yo lo he pisado de niña. Luego les cuento. ¡Daniel! ¡Baja, que los gallegos traen regalos!", "이 무늬, 난 밟아 봤어, 얘야. 어릴 때 밟아 봤어. 이따 얘기해 줄게. 대니얼! 내려와라, 갈레고들이 선물을 가져왔다!"),
(DN, "(bajando la escalera, con una toalla al cuello) ¡Ya voy, mami! Estaba en una llamada con Atlanta. ¡Lucas, Amparo, bienvenidos a casa!", "(목에 수건을 걸치고 계단을 내려오며) 가요, 엄마! 애틀랜타랑 통화 중이었어요. 루카스, 암파로, 집에 온 걸 환영해요!"),
(L, "¿Atlanta? ¿Trabajas también allí?", "애틀랜타요? 거기서도 일해?"),
(DN, "Un cliente. Una cadena grande. Ya te contaré. Hoy no hablamos de business, ¿okay? Hoy se come.", "고객이야. 큰 체인. 나중에 얘기해 줄게. 오늘은 비즈니스 얘기 안 해, 오케이? 오늘은 먹는 날이야."),
(M, "Eso. Daniel, sírveles algo. Y tú, mi'ja, ayúdame con la mesa, que la muchacha se fue temprano.", "그래. 대니얼, 뭐 좀 드려라. 그리고 얘야, 상 차리는 것 좀 도와다오. 도우미가 일찍 갔거든."),
(A, "Yo la ayudo, señora.", "제가 도와드릴게요, 할머님."),
(M, "No, no, tú eres visita. Gaby, ve tú. Y pasa la aspiradora por la carpeta del comedor, que el perro la dejó llena de pelos.", "아니, 아니, 너는 손님이야. 가비, 네가 가라. 그리고 식당 '카르페타'에 청소기 좀 돌려. 개가 털투성이로 만들어 놨어."),
(L, "(a Amparo, en voz baja) ¿La carpeta? ¿Una carpeta con pelos?", "(암파로에게 작은 소리로) 카르페타요? 털 붙은 서류철?"),
(GB, "(riendo) La alfombra, Lucas. Carpet. Aquí la carpeta es la alfombra. Y la carpeta de los papeles es el folder.", "(웃으며) 카펫이요, 루카스. 카펫. 여기선 카르페타가 양탄자예요. 서류 넣는 건 폴더고요."),
(L, "Entonces, si mañana pido una carpeta con los contratos...", "그럼 내일 계약서 든 카르페타를 달라고 하면…"),
(DN, "...te traen una alfombra enrollada, chico. Pide el folder. (le da una cerveza) Toma, una Hatuey. Bueno, una cerveza. Ya no hay Hatuey de verdad, pero el nombre nos recuerda a Cuba.", "…둘둘 만 양탄자를 가져다줄걸, 이 친구야. 폴더라고 해. (맥주를 건네며) 자, 아투에이. 뭐, 그냥 맥주지. 진짜 아투에이는 이제 없지만 이름이 쿠바를 떠올리게 해."),
(A, "Gracias. ¿Y ese cuadro? Parece el Malecón de La Habana.", "고마워요. 저 그림은요? 아바나의 말레콘 같은데요."),
(M, "Es el Malecón, mi'ja. Lo pintó un primo mío en el setenta. De memoria, porque nunca volvió.", "말레콘 맞아, 얘야. 내 사촌이 70년에 그렸어. 기억으로만. 다시는 못 돌아갔거든."),
(L, "¿Y usted ha vuelto a Cuba alguna vez?", "할머님은 쿠바에 다시 가 보신 적 있으세요?"),
(M, "Una vez, en el noventa y ocho. Fui a ver la casa de mis padres. Vivía otra familia dentro. Les dejé jabón y medicinas, y me fui llorando.", "한 번, 98년에. 우리 부모님 집을 보러 갔지. 다른 가족이 살고 있더라. 비누랑 약을 두고 울면서 나왔어."),
(DN, "Mami...", "엄마…"),
(M, "Ya, ya, no lloro. Esta noche no se llora. Esta noche se come.", "그래, 그래, 안 울어. 오늘 밤엔 우는 거 아니야. 오늘 밤엔 먹는 거야."),
(GB, "(desde el comedor) ¡La mesa está lista! Y la carpeta, limpia.", "(식당에서) 상 다 차렸어요! 카르페타도 깨끗해요."),
(L, "¿Limpia de pelos?", "털 없이 깨끗하게요?"),
(GB, "Limpia de pelos. La alfombra, Lucas. Ya vas aprendiendo.", "털 없이 깨끗하게요. 양탄자요, 루카스. 점점 배우시네요."),
(L, "Aprendo más en tres días aquí que en un mes de clases.", "여기서 사흘 동안 배우는 게 한 달 수업보다 많아요."),

("#", "Escena 2 · 20:50 · El comedor", "장면 2 · 오후 8시 50분 · 식당"),
(None, "Sobre la mesa: ropa vieja, arroz moros y cristianos, plátanos maduros fritos, tostones y yuca con mojo. Mercedes se sienta a la cabecera. Daniel abre el vino de Castellón.", "식탁 위에는 로파 비에하, 검은콩 밥 모로스 이 크리스티아노스, 튀긴 잘 익은 플랜틴, 토스톤, 모호 소스를 곁들인 유카가 차려져 있다. 메르세데스가 상석에 앉는다. 대니얼이 카스테욘 와인을 연다."),
(M, "Coman, coman, que la ropa vieja está mejor caliente. Esta receta es de mi suegra, la mujer del asturiano.", "먹어, 먹어. 로파 비에하는 뜨거울 때가 맛있어. 이 요리법은 우리 시어머니, 그 아스투리아스 사람 부인한테서 배운 거야."),
(A, "¡Qué rico está! ¿Por qué se llama ropa vieja?", "정말 맛있어요! 왜 '로파 비에하(헌 옷)'라고 해요?"),
(M, "Porque la carne se deshace en tiras, como un trapo viejo. Los cubanos le ponemos nombre a todo. Al arroz con frijoles negros le decimos moros y cristianos.", "고기가 낡은 천처럼 가닥가닥 찢어지니까. 우리 쿠바 사람들은 뭐든 이름을 붙여. 검은콩 밥은 '무어인과 기독교인'이라고 부르지."),
(L, "Eso suena a historia de España.", "스페인 역사처럼 들리네요."),
(M, "Todo en Cuba suena a historia de España, mi'jo. Para lo bueno y para lo malo.", "쿠바의 모든 게 스페인 역사처럼 들려, 얘야. 좋은 의미로도, 나쁜 의미로도."),
(DN, "Mami, no empieces con la política, que son nuestros invitados.", "엄마, 정치 얘기 시작하지 마요. 손님들이잖아요."),
(M, "No es política, es historia. A mi abuelo inglés le decían «el americano», al asturiano de tu padre le decían «el gallego»... En La Habana nadie era de donde decía que era.", "정치가 아니라 역사야. 우리 영국인 할아버지는 '미국인'이라고 불렀고, 네 아버지 쪽 아스투리아스 양반은 '갈레고'라고 불렀지… 아바나에선 아무도 자기가 말하는 곳 출신이 아니었어."),
(A, "¿Su abuelo era inglés? ¿De ahí viene lo de Walker?", "할아버님이 영국 분이셨어요? 그래서 '워커'가 붙은 거예요?"),
(M, "De ahí. Vino de Jamaica a trabajar de ingeniero en un central azucarero. Se casó con una cubana y ya no se fue nunca.", "그래서지. 자메이카에서 사탕수수 공장 기술자로 일하러 왔어. 쿠바 여자랑 결혼해서 다시는 안 떠났지."),
(GB, "Por eso yo soy Ruiz-Walker también. Los dos apellidos. Como en España, pero con guion, para que los americanos no se líen.", "그래서 저도 루이스-워커예요. 성 두 개. 스페인처럼요. 근데 미국 사람들이 헷갈리지 않게 하이픈을 넣었어요."),
(L, "Muy práctico. En el aeropuerto de Miami me llamaron «señor Ferrer Gil» y luego «señor Gil». Me quedé sin apellido.", "아주 실용적이네요. 마이애미 공항에서 저를 '페레르 힐 씨'라고 불렀다가 '힐 씨'라고 하더라고요. 성 하나를 잃었어요."),
(DN, "¡Bienvenido a América, chico! Aquí todos perdemos algo al llegar.", "아메리카에 온 걸 환영해, 이 친구야! 여기 오면 다들 뭔가 하나씩 잃어."),
(M, "Y ganamos otras cosas. Yo llego aquí en el sesenta y uno con veinte años, dos maletas y un marido que no habla inglés. No conocemos a nadie. Vivimos en un cuarto en la Pequeña Habana.", "그리고 다른 걸 얻지. 난 61년에 스무 살로 여기 와. 가방 두 개에 영어 못 하는 남편 하나. 아는 사람이 아무도 없어. 리틀 아바나의 방 한 칸에서 살아."),
(A, "¿Y cómo empezaron?", "그럼 어떻게 시작하셨어요?"),
(M, "Raúl, mi marido, trabaja de día descargando camiones y de noche estudia inglés. Yo coso vestidos. En el setenta y tres, por fin, abrimos el almacén en Hialeah. Con azulejos, como su padre en La Habana.", "남편 라울은 낮엔 트럭 짐을 내리고 밤엔 영어를 배워. 나는 옷을 지어. 73년에 드디어 하이얼리아에 창고를 열지. 타일을 팔았어, 시아버지가 아바나에서 그랬던 것처럼."),
(L, "Lo de los azulejos viene de lejos, entonces.", "타일 일은 아주 오래된 내력이군요."),
(DN, "De muy lejos. Mi abuelo vendía mosaicos en La Habana. Mi padre vendía azulejos en Hialeah. Yo vendo porcelánico en Brickell. Y Gaby...", "아주 오래됐지. 할아버지는 아바나에서 모자이크 타일을 팔았고, 아버지는 하이얼리아에서 타일을 팔았고, 나는 브리켈에서 자기질 타일을 팔아. 그리고 가비는…"),
(GB, "Y Gaby lo vende todo por Internet y cobra a tiempo. Alguien tiene que hacerlo.", "그리고 가비는 다 인터넷으로 팔고 제때 돈을 받아요. 누군가는 해야 하니까요."),
(M, "(ríe) Esa sale a mí. Raúl era bueno vendiendo, pero cobraba fatal.", "(웃으며) 쟤는 날 닮았어. 라울은 파는 건 잘했는데 돈 받는 건 형편없었지."),
(A, "(sonríe a Gaby) En mi casa pasa lo mismo. Mi padre vende y Ramón cobra.", "(가비에게 웃으며) 우리 집도 똑같아요. 아빠는 팔고 라몬이 받아 내요."),
(DN, "¡Eh! Que yo cobro bien. Pago despacio, pero cobro bien.", "어이! 나 돈 잘 받아. 지불은 천천히 하지만 받는 건 잘한다고."),
(L, "Eso ya nos lo habían dicho.", "그 얘기는 이미 들었어."),
(DN, "¿Quién? ¿Quién te lo dijo? ¡Alejandra! Seguro que fue Alejandra.", "누가? 누가 그래? 알레한드라! 분명 알레한드라지."),
(L, "Un caballero no revela sus fuentes.", "신사는 출처를 밝히지 않는 법이야."),
(M, "(aplaude) ¡Este gallego me gusta! Daniel, este no se deja.", "(손뼉을 치며) 이 갈레고 마음에 드네! 대니얼, 이 사람은 만만치 않구나."),
(DN, "Bueno, ya que no hablamos de business... ¿qué tal el vino de Castellón? Porque esto no es un Rioja.", "자, 비즈니스 얘기는 안 하니까… 카스테욘 와인 어때? 이건 리오하가 아니잖아."),
(L, "No, es de la Plana. Una garnacha de un pequeño productor de al lado de Onda.", "아니, 플라나 지역 거야. 온다 옆 작은 양조장의 가르나차."),
(DN, "Pues está muy bueno. Tendrían que vendernos vino también.", "근데 아주 맛있네. 와인도 우리한테 팔아야겠어."),
(A, "Un producto cada vez. Primero, el suelo.", "한 번에 한 제품씩이요. 먼저 바닥부터."),
(M, "Esta muchacha tiene la cabeza en su sitio. ¿Tienes hijos, mi'ja?", "이 아가씨는 머리가 제자리에 있네. 자식 있니, 얘야?"),
(A, "Uno, Marc, de diez años. Se ha quedado en Onda con mis padres.", "하나요. 열 살 마르크요. 온다에서 저희 부모님이랑 있어요."),
(M, "Diez años. ¡Qué edad tan bonita! ¿Y lo extrañas?", "열 살. 참 예쁜 나이지! 보고 싶지?"),
(A, "Cada noche. Le llamo a las siete de la mañana de aquí, antes de que se vaya a la piscina.", "매일 밤요. 여기 시간 아침 7시에, 걔가 수영장 가기 전에 전화해요."),
(M, "Los hijos se extrañan aunque estén al lado. Este (señala a Daniel) tiene cincuenta y seis años y todavía lo extraño cuando se va a Atlanta.", "자식은 옆에 있어도 보고 싶어. 이 녀석은 (대니얼을 가리키며) 쉰여섯인데도 애틀랜타에 가면 아직도 보고 싶어."),
(DN, "¡Mami, por favor! Que estoy negociando.", "엄마, 제발! 나 지금 협상 중이라고요."),
(GB, "Papi, dijiste que hoy no se hablaba de business.", "아빠, 오늘은 비즈니스 얘기 안 한다면서요."),
(DN, "Y no hablo de business. Me quejo. Es distinto.", "비즈니스 얘기 안 해. 투덜대는 거야. 그건 다르지."),
(L, "En España quejarse también es un deporte nacional.", "스페인에서도 투덜대는 건 국민 스포츠예요."),
(M, "Quejarse y comer. Lo único que no nos quitó nadie.", "투덜대기랑 먹기. 아무도 우리한테서 못 빼앗은 유일한 거지."),
(None, "Gaby trae el postre: una fuente con trozos de una fruta anaranjada.", "가비가 디저트를 내온다. 주황색 과일 조각이 담긴 접시다."),
(L, "¡Qué buena pinta! ¿Eso es pa...?", "맛있어 보이네요! 그거 파…?"),
(GB, "(lo interrumpe rápido) ¡Fruta bomba! Es fruta bomba, Lucas.", "(재빨리 말을 끊으며) 프루타 봄바! 프루타 봄바예요, 루카스."),
(L, "¿Fruta bomba? En España la llamamos...", "프루타 봄바요? 스페인에선 그걸…"),
(DN, "(muerto de risa) ¡Sabemos cómo la llaman, chico! Pero aquí, delante de mi madre, esa palabra no se dice. En Cuba tiene otro sentido. Nada fino.", "(배꼽을 잡고 웃으며) 그걸 뭐라고 부르는지 우리도 알아, 이 친구야! 근데 여기, 우리 엄마 앞에선 그 말 안 해. 쿠바에선 다른 뜻이 있거든. 점잖지 않은 뜻."),
(L, "(se pone rojo) Perdón. En Monterrey aprendí a no decir «coger», y ahora esto.", "(얼굴이 빨개지며) 죄송해요. 몬테레이에선 '코헤르'를 안 쓰는 법을 배웠는데 이번엔 이거네요."),
(M, "Tranquilo, mi'jo. Aquí «coger» puedes decirlo todo lo que quieras. Coges la guagua, coges el teléfono... Lo que no puedes es pedir la otra fruta en la mesa.", "괜찮아, 얘야. 여기선 '코헤르'는 얼마든지 써도 돼. 과과(버스)도 코헤르하고, 전화도 코헤르하고… 식탁에서 그 과일 이름만 안 대면 돼."),
(A, "Cada país tiene una palabra prohibida. Habrá que hacer una lista.", "나라마다 금지어가 하나씩 있네요. 목록을 만들어야겠어요."),
(GB, "Te la hago yo. Tengo amigos de toda Latinoamérica. Es mi especialidad.", "제가 만들어 드릴게요. 라틴아메리카 전역에 친구가 있어요. 제 전문이에요."),
(DN, "Mi hija: cobra a tiempo y sabe todas las palabrotas del continente. ¡Qué orgullo!", "우리 딸: 돈은 제때 받고 대륙의 욕은 다 알지. 자랑스럽기도 하지!"),

("#", "Escena 3 · 22:10 · El portal de la casa", "장면 3 · 오후 10시 10분 · 집 현관 앞 포치"),
(None, "Después del café, Mercedes pide a Gaby que traiga un álbum de fotos antiguo, con las tapas de piel gastadas. Se sientan en el portal, bajo un ventilador de techo. Se oyen las ranas y, a lo lejos, el tráfico de la US-1.", "커피를 마신 뒤 메르세데스가 가비에게 가죽 표지가 닳은 옛 사진첩을 가져오라고 한다. 다들 천장 선풍기 아래 포치에 앉는다. 개구리 소리와 멀리 US-1 도로의 차 소리가 들린다."),
(M, "Miren. Esta es la ferretería del suegro. Calle Muralla, en La Habana Vieja. Mil novecientos cincuenta y dos.", "봐요. 이게 시아버지 철물점이야. 아바나 비에하의 무라야 거리. 1952년."),
(None, "Una fotografía en blanco y negro: un mostrador de madera, estanterías llenas de herramientas, un hombre con bigote y delantal. Y el suelo: un mosaico geométrico, idéntico al de la baldosa que ha traído Amparo.", "흑백 사진. 나무 계산대, 공구로 가득 찬 선반, 콧수염에 앞치마를 두른 남자. 그리고 바닥. 암파로가 가져온 타일과 똑같은 기하학 모자이크 무늬다."),
(A, "(se acerca, sorprendida) Pero... es el mismo dibujo.", "(놀라서 가까이 보며) 그런데… 똑같은 무늬예요."),
(M, "El mismo. Por eso me quedé callada cuando abrí la caja. El suegro decía que esas baldosas venían de Valencia, en barco.", "똑같지. 그래서 상자를 열었을 때 말이 안 나왔던 거야. 시아버지가 그 타일들은 발렌시아에서 배로 왔다고 했어."),
(A, "En los años cincuenta, muchas fábricas de Castellón y de Valencia vendían mosaico hidráulico a Cuba. Mi abuelo me lo contaba. Es posible que...", "50년대엔 카스테욘과 발렌시아의 공장 여러 곳이 쿠바에 시멘트 모자이크 타일을 팔았어요. 할아버지가 얘기해 주셨어요. 어쩌면…"),
(M, "Es posible, mi'ja. Es muy posible que yo haya pisado de niña una baldosa de tu abuelo.", "그럴 수 있지, 얘야. 내가 어릴 때 너희 할아버지 타일을 밟았을 수도 있어."),
(None, "Nadie dice nada durante unos segundos. Daniel mira la foto con una expresión que Lucas no le había visto.", "몇 초 동안 아무도 말이 없다. 대니얼이 루카스가 처음 보는 표정으로 사진을 바라본다."),
(DN, "Mi abuelo perdió la ferretería en el sesenta. Se la quitaron. Llegó aquí con más de cincuenta años y nunca volvió a abrir una tienda. Decía que ya no tenía suelo donde pisar.", "할아버지는 60년에 철물점을 잃었어. 빼앗겼지. 쉰 넘어서 여기 와서 다시는 가게를 열지 않았어. 이제 디딜 바닥이 없다고 하셨지."),
(L, "Lo siento mucho, Daniel.", "정말 유감이야, 대니얼."),
(DN, "No lo sientas. Mi padre abrió el almacén. Yo abrí tres showrooms. Gaby abrirá lo que quiera. El suelo lo seguimos poniendo nosotros. (se aclara la voz) Bueno. Ya está bien de nostalgia, que mi madre se pone a llorar y luego me echa la culpa a mí.", "유감스러워할 거 없어. 아버지가 창고를 열었고, 내가 쇼룸 세 개를 열었고, 가비는 원하는 걸 열겠지. 바닥은 계속 우리가 깔고 있어. (목을 가다듬으며) 자. 향수는 이만하자. 엄마가 울기 시작하면 나중에 나한테 뭐라 하시거든."),
(M, "¡Yo no lloro! Es el ventilador, que me echa aire en los ojos.", "나 안 울어! 선풍기가 눈에 바람을 넣어서 그래."),
(GB, "Claro, abuela. El ventilador.", "그럼요, 할머니. 선풍기죠."),
(L, "Daniel, ¿tu abuelo llegó a ver el almacén de Hialeah?", "대니얼, 할아버지는 하이얼리아 창고를 보셨어?"),
(DN, "Lo vio abrir. El primer día, con su bastón. Pisó el suelo de cemento y dijo: «Esto hay que cubrirlo con algo bonito».", "여는 걸 보셨지. 첫날, 지팡이 짚고. 시멘트 바닥을 밟고 말씀하셨어. '여긴 뭔가 예쁜 걸로 덮어야겠다.'"),
(A, "¿Y lo cubrieron?", "그래서 덮었어요?"),
(DN, "Con las primeras cajas de azulejos que no vendimos. Ese suelo sigue allí. El almacén ahora es la oficina de Gaby.", "첫해에 못 판 타일 상자들로. 그 바닥은 아직 거기 있어. 그 창고가 지금은 가비 사무실이야."),
(GB, "Lo tengo debajo del escritorio. Azul y blanco. Feísimo, pero no lo cambio por nada.", "제 책상 밑에 있어요. 파랑이랑 흰색. 엄청 못생겼는데 무엇과도 안 바꿔요."),
(L, "Entonces la historia de vuestra empresa empieza con un suelo.", "그럼 이 회사의 역사는 바닥 하나로 시작하네요."),
(DN, "Como la vuestra, ¿no? Todo empieza con un suelo.", "너희 회사처럼, 그렇지? 모든 건 바닥에서 시작해."),
(A, "Y con alguien que lo pisa.", "그리고 그걸 밟는 누군가로부터요."),
(M, "Y con alguien que lo barre, mi'ja. No te olvides nunca de los que barren.", "그리고 그걸 쓸고 닦는 누군가로부터지, 얘야. 비질하는 사람들을 절대 잊지 마라."),
(GB, "(ríe) La abuela siempre tiene la última palabra.", "(웃으며) 할머니는 늘 마지막 말씀을 하셔요."),
(M, "Amparo, mi'ja, esta baldosa la voy a poner en mi cuarto, encima del tocador. Dile a tu abuelo que una cubana vieja se la agradece.", "암파로, 얘야, 이 타일은 내 방 화장대 위에 둘게. 너희 할아버지께 늙은 쿠바 할미가 고마워한다고 전해 다오."),
(A, "Mi abuelo murió hace muchos años. Pero se lo diré a mi padre. Le va a emocionar.", "할아버지는 오래전에 돌아가셨어요. 하지만 아빠한테 전할게요. 감동하실 거예요."),
(M, "Y que venga él también. A los padres hay que conocerlos. Así se sabe con quién se hace negocio.", "그리고 아버지도 오시라고 해. 부모는 만나 봐야 해. 그래야 누구랑 장사하는지 알지."),
(DN, "Mami tiene razón. Yo no firmo nada importante sin conocer al dueño. Es una regla de la familia.", "엄마 말이 맞아. 나는 주인을 만나 보지 않고는 중요한 건 서명 안 해. 우리 집 규칙이야."),
(L, "Lo tendremos en cuenta. ¿Aunque el dueño tenga sesenta y cuatro años y no le guste volar?", "명심할게. 주인이 예순넷이고 비행기 타는 걸 싫어해도?"),
(DN, "Aunque tenga cien. Mi madre cruzó el estrecho de Florida con veinte años. Tu jefe puede cruzar el Atlántico con un buen asiento.", "백 살이라도. 우리 엄마는 스무 살에 플로리다 해협을 건넜어. 너네 사장은 좋은 좌석에 앉아서 대서양을 건너면 돼."),
(A, "(sonríe) Se lo diremos con esas mismas palabras.", "(미소 지으며) 그 말 그대로 전할게요."),
(DN, "Bueno. Mañana a las nueve, en el showroom de Doral. Allí hacemos el business de verdad. Esta noche solo era para que me conocieran.", "좋아. 내일 9시, 도랄 쇼룸에서. 진짜 비즈니스는 거기서 해. 오늘 밤은 날 알게 하려는 자리였을 뿐이야."),
(L, "¿Y para conocernos tú a nosotros?", "그리고 네가 우리를 알려는 자리이기도 하고?"),
(DN, "(le guiña un ojo) Eso también, chico. Eso también. Pasaste el examen de la fruta bomba.", "(윙크하며) 그것도 맞아, 이 친구야. 그것도. 프루타 봄바 시험은 통과했어."),
(GB, "Casi, papi. Casi lo suspende.", "거의요, 아빠. 거의 떨어질 뻔했어요."),
(L, "Casi. Pero no lo dije.", "거의요. 하지만 말하진 않았어요."),
(M, "Ay, mi'jo. Lo importante en la vida es eso: casi decirlo y no decirlo. Ve con Dios.", "아이고, 얘야. 인생에서 중요한 건 그거야. 말할 뻔하고 말하지 않는 거. 잘 가거라."),
(None, "Ya en el coche, Amparo saca el móvil. Son las cuatro y media de la mañana en Onda. Escribe un mensaje a su padre y lo deja programado para las ocho: «Papá, aquí hay una señora de ochenta y cinco años que quiere conocerte. Y su hijo también».", "차에 탄 뒤 암파로가 휴대폰을 꺼낸다. 온다는 새벽 4시 반이다. 아빠에게 메시지를 써서 8시에 보내도록 예약해 둔다. '아빠, 여기 여든다섯 된 할머니가 아빠를 만나고 싶어 해요. 그 아들도요.'"),
(L, "¿A quién escribes a estas horas?", "이 시간에 누구한테 써요?"),
(A, "A mi padre. Para las ocho de su mañana. Hay cosas que no se pueden contar por videollamada.", "아빠한테요. 거기 아침 8시에 가게. 화상 통화로는 얘기할 수 없는 것들이 있잖아요."),
(L, "¿Le vas a contar lo de la foto?", "사진 얘기 할 거예요?"),
(A, "Lo de la foto, lo de la baldosa y lo de que aquí nadie firma sin conocer al dueño. Que vaya preparando la maleta.", "사진 얘기, 타일 얘기, 그리고 여기선 아무도 주인을 만나 보지 않고는 서명 안 한다는 얘기까지요. 가방 싸기 시작하시라고요."),
(L, "Tu padre en Miami. Eso sí que no lo había previsto en mi plan de negocio.", "당신 아버지가 마이애미에. 그건 내 사업 계획에도 없던 일인데요."),
(A, "Lucas, en mi familia nada sale en el plan de negocio. Sale en la sobremesa.", "루카스, 우리 집에선 아무것도 사업 계획에서 안 나와요. 식후 담소에서 나오지."),
]

